CREATE INDEX "idx_company_slugs_company" ON "company_slugs" USING btree ("company_id");--> statement-breakpoint
CREATE INDEX "idx_contacts_company" ON "contacts" USING btree ("company_id");--> statement-breakpoint
CREATE INDEX "idx_portfolio_items_company" ON "portfolio_items" USING btree ("company_id");--> statement-breakpoint
